import sharp from 'sharp';
import { mkdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

// Rasterize the existing vector logo and supplied brand font, never redraw them.
// Run only when changing the email artwork; generated bytes ship in the server
// bundle, so sending mail needs neither filesystem reads nor remote fetches.
const root = new URL('../', import.meta.url);
const directory = new URL('work/email-artwork/', root);
await mkdir(directory, { recursive: true });
const images = {};
images.logo = await sharp(
  fileURLToPath(new URL('public/brand/bulk-away-vector.svg', root)),
  { density: 300 },
)
  .resize({ width: 480 })
  .flatten({ background: '#1d1724' })
  .png()
  .toBuffer();
for (const [name, title] of [
  ['crew', 'A fresh start is calling.'],
  ['customer', 'You’re on our radar.'],
]) {
  const text = await sharp({
    text: {
      text: `<span foreground="#1d1724">${title}</span>`,
      fontfile: fileURLToPath(new URL('../fonts/Brookvale-webfont.woff', root)),
      font: 'Brookvale 112',
      rgba: true,
    },
  })
    .png()
    .toBuffer();
  const dimensions = await sharp(text).metadata();
  if (dimensions.width > 1064 || dimensions.height > 144)
    throw new Error('Headline exceeds the email artwork frame');
  images[name] = await sharp({
    create: { width: 1064, height: 144, channels: 3, background: '#f5efd9' },
  })
    .composite([{ input: text, left: 0, top: 8 }])
    .png()
    .toBuffer();
}
for (const [name, bytes] of Object.entries(images))
  await writeFile(new URL(`${name}.png`, directory), bytes);
await writeFile(
  new URL('lib/pickup-email-artwork.generated.ts', root),
  '// Generated by scripts/build-email-artwork.mjs from the supplied logo and Brookvale font.\n' +
    'export const pickupEmailArtwork = ' +
    JSON.stringify(
      Object.fromEntries(
        Object.entries(images).map(([name, bytes]) => [
          name,
          bytes.toString('base64'),
        ]),
      ),
      null,
      2,
    ) +
    ' as const;\n',
);
console.log('Generated embedded email logo and headline artwork.');
